16: export default function Root(_props: RootProps) {
17:   const [accountId, setAccountId] = useState<string | null>(null);
18:   const [loadingAccount, setLoadingAccount] = useState<boolean>(true);
19: 
20:   const loadAccountId = useCallback(() => {
21:     setLoadingAccount(true);
22:     const storedAccountId = getAccountId();
23:     setAccountId((prev) =>
24:       prev !== storedAccountId
25:         ? storedAccountId
26:         : storedAccountId === null
27:         ? null
28:         : `${storedAccountId}`
29:     );
30:     setLoadingAccount(false);
31:   }, []);
32: 
33:   useEffect(() => {
34:     loadAccountId();
35:   }, [loadAccountId]);
36: 
37:   useEffect(() => {
38:     const handleAccountIdChange = (event: Event) => {
39:       const customEvent = event as CustomEvent<{ accountId: string }>;
40:       const newAccountId = customEvent.detail?.accountId || getAccountId();
41:       if (newAccountId) {
42:         setAccountId((currentId) => {
43:           if (currentId !== newAccountId) {
44:             setLoadingAccount(false);
45:             return newAccountId;
46:           }
47:           return currentId;
48:         });
49:       }
50:     };
51: 
52:     const handleStorageChange = (e: StorageEvent) => {
53:       if (e.key === "accountId") {
54:         const newAccountId = e.newValue || getAccountId();
55:         if (newAccountId) {
56:           setAccountId((currentId) => {
57:             if (currentId !== newAccountId) {
58:               setLoadingAccount(false);
59:               return newAccountId;
60:             }
61:             return currentId;
62:           });
63:         }
64:       }
65:     };
66: 
67:     window.addEventListener("accountIdChanged", handleAccountIdChange);
68:     window.addEventListener("storage", handleStorageChange);
69: 
70:     return () => {
71:       window.removeEventListener("accountIdChanged", handleAccountIdChange);
72:       window.removeEventListener("storage", handleStorageChange);
73:     };
74:   }, []);
75: 
76:   const handleRefreshAccount = useCallback(() => {
77:     window.location.reload();
78:   }, []);
79: 
80:   if (loadingAccount) {
81:     return (
82:       <Provider store={store}>
83:         <QueryProvider>
84:           <div className={styles.container}>
85:             <Loading text="Carregando..." size="medium" />
86:           </div>
87:         </QueryProvider>
88:       </Provider>
89:     );
90:   }
91: 
92:   if (!accountId) {
93:     return (
94:       <Provider store={store}>
95:         <QueryProvider>
96:           <InvalidAccountCard handleClick={handleRefreshAccount} />
97:         </QueryProvider>
98:       </Provider>
99:     );
100:   }
101: 
102:   return (
103:     <Provider store={store}>
104:       <QueryProvider>
105:         <div className={styles.container}>
106:           <Dashboard
107:             accountId={accountId}
108:             onRefreshAccount={handleRefreshAccount}
109:           />
110:         </div>
111:       </QueryProvider>
112:     </Provider>
113:   );
114: }

1: export function isWindowAvailable(): boolean {
2:   return typeof window !== "undefined";
3: }
4: 
5: export function isLocalStorageAvailable(): boolean {
6:   return isWindowAvailable() && typeof window.localStorage !== "undefined";
7: }
8: 
9: export function getLocalStorageItem(key: string): string | null {
10:   if (!isLocalStorageAvailable()) {
11:     return null;
12:   }
13: 
14:   try {
15:     return window.localStorage.getItem(key);
16:   } catch (error) {
17:     console.error(`Erro ao ler ${key} do localStorage:`, error);
18:     return null;
19:   }
20: }
21: 
22: export function setLocalStorageItem(key: string, value: string): boolean {
23:   if (!isLocalStorageAvailable()) {
24:     return false;
25:   }
26: 
27:   try {
28:     window.localStorage.setItem(key, value);
29:     return true;
30:   } catch (error) {
31:     console.error(`Erro ao salvar ${key} no localStorage:`, error);
32:     return false;
33:   }
34: }
35: 
36: export function removeLocalStorageItem(key: string): boolean {
37:   if (!isLocalStorageAvailable()) {
38:     return false;
39:   }
40: 
41:   try {
42:     window.localStorage.removeItem(key);
43:     return true;
44:   } catch (error) {
45:     console.error(`Erro ao remover ${key} do localStorage:`, error);
46:     return false;
47:   }
48: }
49: 
50: export function clearLocalStorage(): boolean {
51:   if (!isLocalStorageAvailable()) {
52:     return false;
53:   }
54: 
55:   try {
56:     window.localStorage.clear();
57:     return true;
58:   } catch (error) {
59:     console.error("Erro ao limpar localStorage:", error);
60:     return false;
61:   }
62: }
63: 
64: export function getCurrentPath(): string {
65:   if (!isWindowAvailable()) {
66:     return "";
67:   }
68:   return window.location.pathname;
69: }

